<div class="inventory-toolbar"><div><b>Medicine catalogue</b><span><?= count($data['medicines']) ?> active items</span></div><div class="inventory-legend"><span><i class="legend-low"></i> Low stock &lt; 15</span><span><i class="legend-exp"></i> Expiring within 60 days</span></div></div>
<div class="inventory-table-wrap" id="stock-table"><table class="inventory-table"><thead><tr><th>Medicine</th><th>Type</th><th>Stock</th><th>Next expiry · FEFO</th><th>Batch details</th><th>Price</th><th></th></tr></thead><tbody><?php foreach($data['medicines'] as $m): $low=(int)$m['stock_quantity']<15;$exp=$m['next_expiry']&&strtotime($m['next_expiry'])<=strtotime('+60 days'); ?><tr><td><b><?= e($m['name']) ?></b><small><?= e($m['dosage']) ?></small></td><td><span class="category-badge <?= $m['category']==='RX'?'badge-rx':'badge-otc' ?>"><?= e($m['category']) ?></span></td><td><b class="<?= $low?'stock-low':'' ?>"><?= (int)$m['stock_quantity'] ?></b><?= $low?'<small class="stock-warning">Low stock</small>':'' ?></td><td><?= $m['next_expiry']?e(date('M j, Y',strtotime($m['next_expiry']))):'—' ?><?= $exp?'<small class="expiry-warning">Expiring soon</small>':'' ?></td><td><details class="batch-details"><summary><?= count($m['batches']) ?> batches <span>⌄</span></summary><div><?php foreach($m['batches'] as $b): ?><p><b><?= e($b['batch_number']) ?></b> · <?= (int)$b['stock_quantity'] ?> units · <?= e(date('M j, Y',strtotime($b['expiry_date']))) ?></p><?php endforeach; ?></div></details></td><td><?= money($m['price']) ?></td><td><button class="icon-button edit-medicine" data-medicine='<?= e(json_encode(['id'=>$m['id'],'name'=>$m['name'],'description'=>$m['description'],'category'=>$m['category'],'type'=>$m['type'],'dosage'=>$m['dosage'],'price'=>$m['price']])) ?>' aria-label="Restock <?= e($m['name']) ?>">＋ Restock</button><form method="post" onsubmit="return confirm('Remove this medicine from the catalogue?')"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete_medicine"><input type="hidden" name="medicine_id" value="<?= (int)$m['id'] ?>"><button class="icon-button danger-icon" title="Remove medicine" aria-label="Remove medicine">×</button></form></td></tr><?php endforeach; ?></tbody></table></div>
